def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([5]), fmt([-5]), fmt([0, 0, 0]), fmt([-3, -1, -2, -1]), fmt([2, -2, 2, -2, 2]),
             fmt([1, -1, 1, -1, 1, -1]), fmt([-1, 2, -1, 2, -1]), fmt([3, -4, 5, -2, 6, -8, 1]),
             fmt([0, -1, 0]), fmt([10**9] * 5)]
    for n in (2, 3, 4, 6, 8, 12, 20, 30):
        for _ in range(3):
            lim = rng.choice([3, 10, 100])
            tests.append(fmt([rng.randint(-lim, lim) for _ in range(n)]))
    N = 100000
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(N)]))
    tests.append(fmt([10**9] * N))
    tests.append(fmt([(10**9 if i % 2 == 0 else -10**9 + 1) for i in range(N)]))
    tests.append(fmt([rng.randint(-10**9, 10**9 // 50) for _ in range(N)]))
    return tests
